import Foundation
import NotchworkKit

/// The familiar Portkeeper dashboard, rendered by the shared host. Portkeeper owns every page and validates every action.
@MainActor enum PortkeeperNotchworkUI {
    static func escape(_ text: String) -> String {
        text.replacingOccurrences(of: "&", with: "&amp;").replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;").replacingOccurrences(of: "\"", with: "&quot;").replacingOccurrences(of: "'", with: "&#39;")
    }
    static func interface(_ model: PortkeeperModel) -> ActivityInterface {
        let services: [[String: Any]] = model.configs.map { config in
            let status: String, active: Bool, issue: Bool, occupied: Bool
            switch model.state(for: config) {
            case .running: status = "Running"; active = true; issue = false; occupied = false
            case .starting: status = "Starting"; active = true; issue = false; occupied = false
            case .unhealthy(let message): status = message; active = true; issue = true; occupied = false
            case .failed(let message): status = message; active = false; issue = true; occupied = false
            case .occupied(let listener): status = "IN USE · \(config.port ?? 0) · \(listener.process) (PID \(listener.pid))"; active = false; issue = true; occupied = true
            case .stopped: status = config.port.map { ":\($0) · \(config.command)" } ?? config.command; active = false; issue = false; occupied = false
            }
            return ["id": config.id.uuidString, "name": String(config.name.prefix(120)), "group": String(config.group.prefix(120)),
                    "status": status, "port": config.port.map(String.init) ?? "tunnel", "active": active, "issue": issue,
                    "occupied": occupied, "hasOutputIssue": issue && !occupied, "hasAddress": config.port != nil || !config.url.isEmpty]
        }
        let listeners: [[String: Any]] = model.listeners.map {
            ["id": $0.id, "port": $0.port, "process": String($0.process.prefix(120)), "pid": $0.pid, "address": String($0.address.prefix(120))]
        }
        func encoded() -> String {
            let state: [String: Any] = ["services": services, "listeners": listeners,
                "serviceCount": model.configs.count, "listenerCount": model.listeners.count,
                "running": model.configs.filter { model.state(for: $0).terminalActive }.count,
                "issues": model.activeIssues.count + (model.scanError == nil ? 0 : 1),
                "scanFailed": model.scanError != nil, "scanError": model.scanError ?? "", "recent": String((model.recentProject ?? "").prefix(120)),
                "tab": model.notchworkTab, "query": model.notchworkSearch, "notice": model.notchworkNotice, "route": model.notchworkPages.snapshot]
            guard let data = try? JSONSerialization.data(withJSONObject: state, options: [.sortedKeys]),
                  let json = String(data: data, encoding: .utf8) else { return "{}" }
            return json
        }
        return ActivityInterface(html: document, height: model.notchworkPages.size.height,
            actions: ["page", "service", "project", "listener", "open", "refresh", "ui", "service.start", "service.stop", "service.restart", "project.restart"],
            width: model.notchworkPages.size.width, stateJSON: encoded(), keepOpen: model.notchworkPages.page != "dashboard")
    }
    static let document = #"""
    <style>
    :root{--ink:#c4f5cc;--muted:#73a37d;--green:#5cff7a;--line:#1f4026;--well:#030604;--raised:#06160a}
    html,body{height:100%;overflow:hidden}body{font:11px Menlo,ui-monospace,monospace;color:var(--ink);background:#000}button,input{font:inherit}button{color:var(--green);background:#000;border:1px solid var(--line);border-radius:6px;cursor:pointer}button:hover{background:var(--raised)}button:disabled{opacity:.35;cursor:default}button:focus-visible,input:focus-visible{outline:2px solid var(--green);outline-offset:2px}button svg{width:13px;height:13px;display:block}svg{fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;flex:none}.icon{width:26px;height:28px;display:inline-flex;align-items:center;justify-content:center;flex:none}.quiet{border-color:transparent}.brand{display:flex;gap:12px;align-items:center;padding:17px 18px 14px;border-bottom:1px solid #142a19}.brand>svg{width:40px;height:40px;color:var(--green)}h1{font-size:18px;letter-spacing:-.3px;margin:0 0 4px;font-weight:600}.subtitle{color:var(--muted);font-size:10px;line-height:1.5}.brand .icon{margin-left:auto}.app{height:100%;display:flex;flex-direction:column}.tabs{display:flex;gap:6px;padding:13px 18px 12px}.tabs button{flex:1;height:30px;color:var(--muted);font-size:12px}.tabs button[aria-selected=true]{background:var(--raised);color:var(--ink)}.tabs svg{width:12px;height:12px;vertical-align:-2px;margin-right:7px}.pane{flex:1;min-height:0;overflow:auto;padding:0 16px 18px;scrollbar-width:thin;scrollbar-color:#25472d #000}.pane[hidden]{display:none}section{margin-bottom:15px}.group{display:flex;gap:5px;align-items:center;padding:0 8px 4px;font-size:10px;letter-spacing:1.3px;color:var(--muted)}.group b{font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}.group>span{color:var(--green)}.group .icon{width:20px;height:20px}.service{display:flex;gap:8px;align-items:center;padding:9px 10px;background:var(--well);border:1px solid #102416;border-radius:6px;margin-top:4px}.dot{width:8px;height:8px;flex:none;border-radius:50%;background:#39513e;margin:0 3px}.dot.active,.dot.issue{background:var(--green)}.name{flex:1;min-width:0}.name strong{font-size:13px;font-weight:600;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.name small{font-size:10px;color:var(--muted);display:block;margin-top:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.controls{display:flex;gap:1px;flex:none}.controls .icon{width:22px}.controls .toggle{width:28px;margin-left:2px;color:var(--ink)}footer{display:flex;align-items:center;gap:12px;padding:12px 17px;border-top:1px solid #142a19}.primary{background:var(--green);color:#000;font-weight:600;padding:7px 10px}.primary:hover{background:#9affad}footer .handoff{border:0;font-size:11px;padding:0}footer .icon{margin-left:auto}.filter{display:flex;align-items:center;gap:8px;padding:10px;margin-bottom:10px;border:1px solid var(--line);border-radius:6px;background:var(--well)}.filter input{width:100%;background:transparent;color:var(--ink);border:0;outline:none;min-width:0}.filter svg{width:12px;height:12px;color:var(--muted)}.listener{display:flex;align-items:center;gap:8px;background:var(--well);border:1px solid #102416;border-radius:6px;padding:8px 10px;margin-bottom:4px}.port{color:var(--green);font-size:14px;font-weight:600;width:53px;flex:none}.listener .name strong{font-size:12px}.empty{color:var(--muted);text-align:center;padding:60px 12px;line-height:1.7}.overflow{font-size:10px;color:var(--muted);line-height:1.6}.overflow button{padding:5px 8px}.notice{font-size:10px;color:var(--muted);padding:0 18px 8px}.notice:empty{display:none}@media(max-width:360px){.brand{padding-left:12px;padding-right:12px}.pane{padding-left:8px;padding-right:8px}.service{gap:4px;padding-left:5px;padding-right:5px}.controls .optional{display:none}footer{gap:7px;padding-left:10px;padding-right:10px}}
    </style>
    <main class="app">
      <header class="brand"><svg viewBox="0 0 40 40" aria-hidden="true"><rect x="5" y="7" width="30" height="26" rx="3"/><path d="m11 14 6 6-6 6m12 0h7"/></svg><div><h1>portkeeper_</h1><div class="subtitle" id="summary">Connecting…</div></div><button class="icon" data-action="refresh" title="Scan ports now" aria-label="Scan ports now">↻</button></header>
      <button class="active-terminals" data-action="open" data-op="workspace"><span>▥ Active terminals</span><span>Pin all active</span></button>
      <nav class="tabs" role="tablist"><button role="tab" aria-selected="true" data-tab="services" aria-controls="services">▱ Services</button><button role="tab" aria-selected="false" data-tab="ports" aria-controls="ports">⌘ Ports</button></nav>
      <div id="services" class="pane" role="tabpanel" aria-label="Services"></div>
      <div id="ports" class="pane" role="tabpanel" aria-label="Ports" hidden><label class="filter"><span aria-hidden="true">⌕</span><input id="query" placeholder="Filter by port or process" aria-label="Filter by port or process"></label><div id="listeners"></div></div>
      <div id="notice" class="notice" role="status" aria-live="polite"></div>
      <footer><button class="primary" data-action="open" data-op="add">+ Add service</button><button class="handoff" data-action="open" data-op="handoff">↥ Project handoff</button><button class="icon quiet" data-action="open" data-op="settings" title="Portkeeper settings" aria-label="Portkeeper settings">⚙</button></footer>
    </main>
    <script>
    let state={},tab='services',query='',queryTimer;
    const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const paths={play:'m8 5 11 7-11 7z',stop:'M6 6h12v12H6z',restart:'M20 11a8 8 0 1 0-2 6M20 4v7h-7',more:'M5 12h.01M12 12h.01M19 12h.01',terminal:'M4 5h16v14H4zM7 9l3 3-3 3m6 0h4',open:'M7 17 17 7M7 7h10v10',ai:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',side:'M4 5h16v14H4zM14 5v14'};
    function icon(name){return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+paths[name]+'"/></svg>'}
    function button(action,op,id,label,symbol,extra='',disabled=false){return '<button class="icon '+extra+'" data-action="'+action+'" data-op="'+op+'" data-id="'+esc(id)+'" aria-label="'+esc(label)+'" title="'+esc(label)+'" '+(disabled?'disabled':'')+'>'+icon(symbol)+'</button>'}
    function replace(id,html){const el=document.getElementById(id);if(el.innerHTML!==html){const top=el.scrollTop;el.innerHTML=html;el.scrollTop=top}}
    function render(){
      document.getElementById('summary').textContent=(state.listenerCount||0)+' listening ports · '+(state.running||0)+' managed'+(state.issues?' · '+state.issues+' issues':'');
      document.getElementById('notice').textContent=state.notice||'';
      const services=state.services||[],groups=[...new Set(services.map(s=>s.group))].sort((a,b)=>a===state.recent?-1:b===state.recent?1:a.localeCompare(b));
      let rows=groups.map(g=>{const entries=services.filter(s=>s.group===g),active=entries.some(s=>s.active);return '<section><div class="group"><span>›</span><b>'+esc(g.toUpperCase())+'</b>'+button('project','more',g,'Edit or delete '+g,'more','quiet')+button('project','restart',g,'Restart all services in '+g,'restart','quiet')+button('project',active?'stop':'start',g,(active?'Stop':'Start')+' all in '+g,active?'stop':'play')+'</div>'+entries.map(s=>'<article class="service"><span class="dot '+(s.issue?'issue':s.active?'active':'')+'"></span><div class="name"><strong>'+esc(s.name)+'</strong><small>'+esc(s.status)+'</small></div><div class="controls">'+button('service','terminal',s.id,'Open '+s.name+' terminal','side','quiet optional')+(s.hasOutputIssue?button('service','output',s.id,'View startup output','terminal','quiet'):'')+(s.issue?button('service','ai',s.id,'Copy AI prompt for '+s.name,'ai','quiet optional'):'')+(s.hasAddress?button('service','address',s.id,'Open '+s.name+' local address','open','quiet optional'):'')+button('service','more',s.id,'Edit, output, or remove '+s.name,'more','quiet')+button('service',s.active?'stop':'start',s.id,s.occupied?'Port belongs to another process':(s.active?'Stop ':'Start ')+s.name,s.active?'stop':'play','toggle',s.occupied)+'</div></article>').join('')+'</section>'}).join('');
      if(!services.length)rows='<div class="empty">No services yet.<br>Add a command to start it from the notch.</div>';
      if(services.length<state.serviceCount)rows+='<p class="overflow">'+(state.serviceCount-services.length)+' more services in the full workspace. <button data-action="open" data-op="workspace">Open workspace</button></p>';
      replace('services',rows);renderPorts();selectTab(tab,false);
    }
    function renderPorts(){const q=query.toLowerCase();const rows=(state.listeners||[]).filter(p=>(p.port+' '+p.process+' '+p.address).toLowerCase().includes(q));let html=state.scanFailed?'<p class="overflow">'+esc(state.scanError)+' <button data-page="scanAI">Copy AI prompt</button></p>':'';html+=rows.map(p=>'<article class="listener"><span class="port">:'+p.port+'</span><div class="name"><strong>'+esc(p.process)+'</strong><small>PID '+p.pid+' · '+esc(p.address)+'</small></div>'+button('listener','ai',p.id,'Explain port '+p.port,'ai','quiet')+button('listener','stop',p.id,'Review stopping '+p.process,'stop','quiet')+'</article>').join('');if(!rows.length)html+='<div class="empty">No matching listening ports.</div>';if((state.listeners||[]).length<state.listenerCount)html+='<p class="overflow">More listeners are available in <button data-action="open" data-op="ports">Portkeeper’s workspace</button>.</p>';replace('listeners',html)}
    function selectTab(value,send=true){tab=value;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===tab)));document.getElementById('services').hidden=tab!=='services';document.getElementById('ports').hidden=tab!=='ports';if(send)notchwork.invoke('ui',JSON.stringify({tab,query}))}
    window.addEventListener('notchwork:state',e=>{state=e.detail||{};tab=state.tab||tab;if(document.activeElement!==document.getElementById('query')){query=state.query||'';document.getElementById('query').value=query}render()});
    document.addEventListener('click',e=>{const t=e.target.closest('[data-tab]');if(t){selectTab(t.dataset.tab);return}const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;notchwork.invoke(b.dataset.action,JSON.stringify({op:b.dataset.op||'',id:b.dataset.id||''}));});
    document.getElementById('query').addEventListener('input',e=>{query=e.target.value;renderPorts();clearTimeout(queryTimer);queryTimer=setTimeout(()=>notchwork.invoke('ui',JSON.stringify({tab,query})),180)});
    if(notchwork.state){state=notchwork.state;tab=state.tab||tab;query=state.query||'';document.getElementById('query').value=query;render()}
    </script>
    <style>
    [hidden]{display:none!important}.page{height:100%;display:flex;flex-direction:column;padding:22px;gap:14px;min-height:0}.page h2{font-size:20px;font-weight:600;margin:0 0 5px;letter-spacing:-.4px}.page p{font-size:11px;color:var(--muted);line-height:1.5;margin:0}.page .actions{display:flex;flex-direction:column;gap:8px}.page .actions button{padding:11px 12px;text-align:left;display:flex;align-items:center;gap:10px;color:var(--ink);background:var(--well);min-height:39px}.page .actions button:after{content:'›';margin-left:auto;color:var(--muted)}.page .actions button:hover{background:var(--raised)}.page .bottom.editor-bottom{justify-content:flex-end}.page .bottom{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:auto;flex:none}.page button{padding:7px 10px}.page .primary{color:#000}.page label{display:flex;flex-direction:column;gap:5px;font-size:11px;color:var(--muted)}.page input,.page textarea{width:100%;background:var(--well);color:var(--ink);border:1px solid var(--line);border-radius:6px;padding:7px 9px;min-width:0;font:11px Menlo,monospace}.page input{height:30px}.page textarea{resize:none;flex:1;min-height:80px;font-size:12px;line-height:1.5}.page .form{display:flex;flex-direction:column;gap:11px}.page .row{display:flex;align-items:center;gap:8px}.page .row>input,.page .row>label{flex:1}.page .row button{flex:none}.page .box{background:var(--well);border:1px solid var(--line);border-radius:6px;padding:13px;line-height:1.5;overflow-wrap:anywhere}.page .box strong{font-size:14px;display:block;margin-bottom:6px}.page .box code{font:11px Menlo,monospace;white-space:pre-wrap;color:var(--muted)}.page .scroller{min-height:0;overflow:auto;flex:1;display:flex;flex-direction:column;gap:10px}.page .error{color:var(--green);font-size:11px;line-height:1.5;flex:none}.page .error:empty{display:none}.page .log{font:11px Menlo,monospace;background:#000;white-space:pre-wrap;overflow-wrap:anywhere;overflow:auto;flex:1;min-height:0;margin:0;border:1px solid var(--line);border-radius:8px;padding:10px;color:var(--ink);tab-size:4}.page .heading-row{display:flex;align-items:center;gap:8px}.page .heading-row h2{font-size:17px;flex:1}.page .heading-row button{font-size:11px;white-space:nowrap}.page select{font:10px Menlo,monospace;background:#030604;color:var(--ink);border:1px solid var(--line);border-radius:5px;padding:5px;max-width:135px}.terminal-body{display:flex;flex-direction:column;gap:8px;min-height:0}.log-tools{font-size:10px}.page .log-tools button{padding:5px}.page .hint{font-size:10px;color:var(--muted)}.page .terminal-card{min-height:200px;display:flex;flex-direction:column;gap:8px;padding:12px;background:var(--well);border:1px solid var(--line);border-radius:6px}.page .terminal-card .log{min-height:110px;max-height:300px}.page .terminal-card header{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.page .terminal-card header strong{flex:1;font-size:13px}.page .terminal-card header button{padding:4px 6px;font-size:10px}.active-terminals{margin:10px 18px 0;padding:10px;display:flex;justify-content:space-between;background:var(--well);text-align:left;color:var(--ink)}.page .subtle{color:var(--muted)}@media(prefers-reduced-motion:no-preference){.page{animation:arrive .15s ease-out}@keyframes arrive{from{opacity:.4}to{opacity:1}}}
    </style>
    <section id="page" class="page" hidden aria-label="Portkeeper controls"></section>
    <script>
    let routeToken='',fieldRevision=-1,draftTimer,fontSize=11,terminalID='';
    const pageButton=(op,label,primary=false,extra='')=>'<button data-page="'+op+'" class="'+(primary?'primary':'')+'" '+extra+'>'+label+'</button>';
    const heading=(title,detail='')=>'<div><h2>'+esc(title)+'</h2><p>'+esc(detail)+'</p></div>';
    const bottom=(op='back',label='Cancel',right='')=>'<div class="bottom">'+pageButton(op,label)+right+'</div>';
    const field=(name,label,extra='')=>'<label>'+label+'<input name="'+name+'" autocomplete="off" spellcheck="false" '+extra+'></label>';
    const actions=items=>'<div class="actions">'+items.map(i=>pageButton(i[0],i[1])).join('')+'</div>';
    function draft(){const result={};document.querySelectorAll('#page [name]').forEach(e=>{if(e.name!=='input'||e.dataset.id===terminalID)result[e.name]=e.value});return result}
    function pageSend(op,id=''){clearTimeout(draftTimer);terminalID=id||terminalID;notchwork.invoke('page',JSON.stringify({op,id,token:routeToken,fields:draft()}))}
    function renderPage(){
     const p=state.route||{page:'dashboard'},name=p.page,container=document.getElementById('page');
     document.querySelector('main.app').hidden=name!=='dashboard';container.hidden=name==='dashboard';
     if(name==='dashboard'){routeToken=p.token||'';return}
     let html='';
     if(routeToken!==p.token){
     routeToken=p.token;fieldRevision=-1;clearTimeout(draftTimer);
     switch(name){
     case 'serviceActions':html=heading(p.name,p.group)+actions([['edit','✎　Edit service'],['output','▤　View output'],['restart','↻　Restart service'],['activate','▥　Make terminal active'],['remove','−　Remove service']])+bottom('back','Back to services');break;
     case 'projectActions':html=heading(p.identity,p.count+' services in this project')+actions([['add','+　Add service'],['restart','↻　Restart project'],['rename','✎　Rename project'],['remove','−　Delete project']])+bottom('back','Back to services');break;
     case 'serviceEditor':html=heading(p.isNew?'Add service':'Edit service','A command runs in its project folder until you stop it.')+'<form class="form" id="service-form">'+field('name','Name','placeholder="Service name"')+field('group','Group','placeholder="My project"')+'<label>Project folder<div class="row"><input name="directory" spellcheck="false" autocomplete="off">'+pageButton('browse','Browse…')+'</div></label>'+field('command','Command','placeholder="Foreground start command"')+'<div class="row">'+field('port','Expected port','inputmode="numeric" placeholder="Optional"')+field('url','Open URL','placeholder="Optional"')+'</div></form><p>The port is used to flag conflicts. Leave it blank for tunnels or tasks without a local listener.</p>'+'<div class="bottom editor-bottom">'+pageButton('back','Cancel')+pageButton('save','Save',true)+'</div>';break;
     case 'projectEditor':html=heading('Rename project',p.count+' services will use this project name.')+field('name','Project name')+bottom('back','Cancel',pageButton('save','Save project',true));break;
     case 'serviceDelete':html=heading('Remove service?','Remove '+p.name+' from '+p.group+'.')+'<div class="box"><strong>'+esc(p.name)+'</strong><code>'+esc(p.command)+'</code><p>A running process will be asked to stop. Its saved output will be removed.</p></div>'+bottom('back','Cancel',pageButton('delete','Remove service',true));break;
     case 'projectDelete':html=heading('Delete project?',p.identity+' contains '+p.count+' services.')+'<div class="box"><strong>'+esc(p.identity)+'</strong><p>Its saved services and logs will be removed.'+(p.running?' '+p.running+' running services will be asked to stop.':'')+'</p></div>'+bottom('back','Cancel',pageButton('delete','Delete project',true));break;
     case 'handoff':html=heading('Project handoff','Give your coding platform the brief, then import its project JSON.')+actions([['copy','▢　Copy Markdown brief'],['saveBrief','↓　Save Markdown brief…'],['paste','▤　Paste project JSON'],['importFile','↥　Import project JSON…']])+bottom('back','Back to services');break;
     case 'pasteJSON':html='<div class="heading-row">'+heading('paste project.json','Paste the handoff, then review its services and commands.')+pageButton('paste','Paste')+'</div><textarea name="json" aria-label="Project JSON" spellcheck="false" placeholder="{&#10;  &quot;version&quot;: 1,&#10;  &quot;project&quot;: &quot;My project&quot;,&#10;  &quot;services&quot;: […]&#10;}"></textarea><div class="row"><label>BASE FOLDER · for relative paths<input name="baseDirectory" aria-label="Base folder" placeholder="Not needed for absolute paths"></label>'+pageButton('browse','Choose…')+'</div>'+bottom('handoff','Back',pageButton('review','Review project',true));break;
     case 'importReview':html=heading('Import '+p.name,(p.importServices||[]).length+' services · Review the commands Portkeeper will be able to run.')+'<div class="scroller">'+(p.importServices||[]).map((s,i)=>'<div class="box"><strong>'+(i+1)+'. '+esc(s.name)+' <small class="subtle">'+esc(s.port)+'</small></strong><code>'+esc(s.command)+'</code><p>'+esc(s.directory)+'</p></div>').join('')+'</div><p>Matching names in this project are updated. Occupied ports are skipped; other processes are never stopped.</p>'+bottom('back','Cancel','<div class="row">'+pageButton('importOnly','Import only')+pageButton('importStart','Import &amp; Start',true)+'</div>');break;
     case 'stopListener':html=heading('Stop listener?',p.managed?'This stops the Portkeeper service '+p.managed+' and its child processes.':'Portkeeper will ask this process to quit gracefully.')+'<div class="box"><strong>'+esc(p.process)+' · PID '+p.pid+'</strong><p>'+esc(p.address)+'</p>'+((p.otherPorts||[]).length?'<p>It also listens on '+p.otherPorts.map(n=>':'+n).join(', ')+'.</p>':'')+'</div>'+bottom('ports','Cancel',pageButton('stop','Stop process',true));break;
     case 'stopResult':html=heading('Port action',p.fields.message)+bottom('ports','Back to ports');break;
     case 'output':html='<div class="heading-row">'+pageButton('back','‹','', 'aria-label="Back to services"')+'<h2>'+esc(p.name)+'</h2>'+pageButton('pin','♧ Pin')+pageButton('ai','Copy AI prompt')+'</div><pre id="output" class="log" tabindex="0" aria-label="Recent output"></pre><div class="bottom"><span class="hint">Recent output · AI prompts redact secrets</span><div>'+pageButton('fontSmaller','A−')+pageButton('fontLarger','A+')+'</div></div>';break;
     case 'terminals':html=heading('Active terminals','Live output and input for your active services.')+'<div id="terminal-list" class="scroller"></div>'+bottom('back','Back to services');break;
     case 'settings':html=heading('Portkeeper','Notchwork provides the shared notch container.')+'<div class="box"><p id="connection"></p></div>'+actions([['retry','↻　Reconnect Notchwork'],['quit','Quit Portkeeper']])+bottom('back','Back to services');break;
     }
     container.innerHTML=html+'<div id="page-error" class="error" role="alert"></div><div id="page-notice" class="hint" role="status"></div>';
     }
     if(p.fieldRevision!==fieldRevision){fieldRevision=p.fieldRevision;container.querySelectorAll('[name]').forEach(e=>{const v=name==='terminals'?(p.terminals||[]).find(t=>t.id===e.dataset.id)?.inputDraft||'':p.fields?.[e.name]||'';if(e.value!==v&&(name!=='terminals'||document.activeElement!==e||e.dataset.id===terminalID))e.value=v})}
     if(name==='output')setLog('output',p.output||'');
     if(name==='settings')document.getElementById('connection').textContent=p.connection||'';

     document.getElementById('page-error').textContent=p.error||'';
     document.getElementById('page-notice').textContent=state.notice||'';
     container.querySelectorAll('button').forEach(b=>b.disabled=!!p.busy);
    if(name==='terminals')renderTerminals(p.terminals||[]);
     if(name==='pasteJSON'){const b=container.querySelector('[data-page=review]');b.disabled=!!p.busy||!container.querySelector('[name=json]').value.trim()}
     if(name==='serviceEditor'){const b=container.querySelector('[data-page=save]'),f=draft();b.disabled=!!p.busy||!['name','group','directory','command'].every(k=>f[k]?.trim())||!!(f.port&&(!/^\d+$/.test(f.port)||+f.port<1||+f.port>65535))}
    }

    const dashboardRender=render;render=()=>{dashboardRender();renderPage()};
    document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(!b||b.disabled)return;e.preventDefault();if(b.dataset.page==='fontSmaller'||b.dataset.page==='fontLarger'){fontSize=Math.max(9,Math.min(18,fontSize+(b.dataset.page==='fontLarger'?1:-1)));renderPage();return}pageSend(b.dataset.page,b.dataset.id||'')});
    document.getElementById('page').addEventListener('input',e=>{terminalID=e.target.dataset.id||terminalID;clearTimeout(draftTimer);draftTimer=setTimeout(()=>pageSend('draft',terminalID),200);if(state.route?.page==='serviceEditor'||state.route?.page==='pasteJSON'){const b=document.querySelector('#page [data-page=save],#page [data-page=review]');if(b)b.disabled=false}});
    document.getElementById('page').addEventListener('submit',e=>{e.preventDefault();pageSend('save')});
    document.getElementById('page').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();pageSend('back')}if(e.key==='Enter'&&e.target.tagName==='INPUT'){e.preventDefault();pageSend(e.target.name==='input'?'input':state.route.page==='projectEditor'||state.route.page==='serviceEditor'?'save':'draft',e.target.dataset.id||'')}});
    const logOptions=new Map();let terminalFilter='',terminalStatus='All',terminalGroup='Project';
    function logState(id){if(!logOptions.has(id))logOptions.set(id,{query:'',level:'All lines',wrap:true,follow:true});return logOptions.get(id)}
    function logToolbar(id){return '<div class="row log-tools" data-log="'+id+'"><input data-log-query="'+id+'" aria-label="Find in output" placeholder="Find in output"><select data-log-level="'+id+'" aria-label="Output level">'+['All lines','Errors','Warnings','Inputs'].map(v=>'<option>'+v+'</option>').join('')+'</select><button data-log-wrap="'+id+'" title="Toggle line wrapping">Wrap</button><button data-log-copy="'+id+'">Copy</button><button data-log-follow="'+id+'">Following</button></div>'}
    function filteredOutput(id,value){const o=logState(id);return value.split('\n').filter(line=>(!o.query||line.toLowerCase().includes(o.query.toLowerCase()))&&(o.level==='All lines'||(o.level==='Errors'?/error|fatal|exception|failed|eaddrinuse/i:o.level==='Warnings'?/warn/i:/\[input\]/i).test(line))).join('\n')}
    const originalRenderPage=renderPage;renderPage=()=>{originalRenderPage();if(state.route?.page==='output'){const log=document.getElementById('output');if(!document.querySelector('[data-log=output]'))log.insertAdjacentHTML('beforebegin',logToolbar('output'));setLog('output',state.route.output||'')}};
    function renderTerminals(items){const p=state.route,list=document.getElementById('terminal-list');fontSize=p.fontSize||11;
     if(!document.getElementById('terminal-filter')){list.insertAdjacentHTML('beforebegin','<div class="row"><input id="terminal-filter" placeholder="Find service, project, command, port" aria-label="Find active terminals"><select id="terminal-add" aria-label="Add terminal"><option value="">Add…</option></select><button data-page="addAll">Add all running</button></div><div class="row"><label>Show<select id="terminal-status">'+['All','Active','Issues','Inactive'].map(v=>'<option>'+v+'</option>').join('')+'</select></label><label>Group<select id="terminal-group">'+['Project','Status','None'].map(v=>'<option>'+v+'</option>').join('')+'</select></label><button data-terminal-font="-1">A−</button><button data-terminal-font="1">A+</button></div>');document.getElementById('terminal-filter').value=terminalFilter;document.getElementById('terminal-status').value=terminalStatus;document.getElementById('terminal-group').value=terminalGroup}
     const add=document.getElementById('terminal-add'),options='<option value="">Add…</option>'+(p.available||[]).filter(c=>!items.some(t=>t.id===c.id)).map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('');if(add.innerHTML!==options)add.innerHTML=options;
     const filtered=items.filter(t=>(t.name+' '+t.group+' '+t.command+' '+t.port).toLowerCase().includes(terminalFilter.toLowerCase())&&(terminalStatus==='All'||(terminalStatus==='Active'?t.active:terminalStatus==='Issues'?t.issue:!t.active)));
     const group=t=>terminalGroup==='Project'?t.group:terminalGroup==='Status'?t.status:'Terminals';const sorted=filtered.slice().sort((a,b)=>group(a).localeCompare(group(b)));const ids=sorted.map(t=>t.id+':'+t.collapsed+':'+group(t)).join(',');
     if(list.dataset.ids!==ids){const saved={};list.querySelectorAll('input[name=input]').forEach(e=>saved[e.dataset.id]=e.value);list.dataset.ids=ids;let previous='';list.innerHTML=sorted.length?sorted.map(t=>{const g=group(t),head=g!==previous?'<div class="group"><b>// '+esc(g.toUpperCase())+'</b>'+(terminalGroup==='Project'?'<button data-action="project" data-op="restart" data-id="'+esc(g)+'">Restart project</button>':'')+'</div>':'';previous=g;return head+'<article class="terminal-card" data-card="'+t.id+'" style="min-height:'+(t.collapsed?'auto':'260px')+'"><header>'+pageButton('collapse',t.collapsed?'›':'⌄',false,'data-id="'+t.id+'" aria-label="Toggle '+esc(t.name)+' output"')+'<strong>'+esc(t.name)+'</strong><small>'+esc(t.status)+'</small>'+pageButton('restart','↻',false,'data-id="'+t.id+'" title="Restart service"')+pageButton('detach','↗',false,'data-id="'+t.id+'" title="Pop out terminal"')+pageButton('unpin','×',false,'data-id="'+t.id+'" title="Remove active terminal"')+'</header><p>'+esc(t.group)+(t.port?' · :'+t.port:'')+'</p><div class="terminal-body" '+(t.collapsed?'hidden':'')+'>'+logToolbar('log-'+t.id)+'<pre class="log" id="log-'+t.id+'" tabindex="0"></pre><div class="row"><input name="input" data-id="'+t.id+'" aria-label="Input to '+esc(t.name)+'" placeholder="Send a line to this service">'+pageButton('input','Send',true,'data-id="'+t.id+'"')+'</div><div class="row">'+pageButton('ai','Copy AI prompt',false,'data-id="'+t.id+'"')+pageButton('workspace','Open workspace',false,'data-id="'+t.id+'"')+'<button data-toggle-id="'+t.id+'"></button><select data-terminal-color="'+t.id+'" aria-label="Terminal color">'+['Seafoam','Sky','Amber','Orchid','Rose','Lime','Periwinkle','Peach'].map((c,i)=>'<option value="'+i+'">'+c+'</option>').join('')+'</select></div></div></article>'}).join(''):'<p>No terminals in this view. Use Add to select services, or clear the filters. Selecting a terminal never starts its command.</p>';list.querySelectorAll('input[name=input]').forEach(e=>e.value=saved[e.dataset.id]??items.find(t=>t.id===e.dataset.id)?.inputDraft??'');list.querySelectorAll('[data-log-query]').forEach(e=>e.value=logState(e.dataset.logQuery).query);list.querySelectorAll('[data-log-level]').forEach(e=>e.value=logState(e.dataset.logLevel).level)}
     filtered.forEach(t=>{setLog('log-'+t.id,t.output);const input=list.querySelector('input[data-id="'+t.id+'"]');input.disabled=!t.input;const send=list.querySelector('[data-page=input][data-id="'+t.id+'"]');send.disabled=!t.input;const toggle=list.querySelector('[data-toggle-id="'+t.id+'"]');toggle.textContent=t.active?'Stop':'Start';toggle.dataset.page=t.active?'stop':'start';toggle.dataset.id=t.id;const color=list.querySelector('[data-terminal-color="'+t.id+'"]');color.value=t.color;list.querySelector('[data-card="'+t.id+'"]').style.borderColor=['#6ed4ba','#70bafa','#f5c263','#cc9ef5','#fc91a6','#b0d66b','#9eadff','#fcab7a'][t.color%8]})
    };
    const sendExtra=(op,extra={})=>notchwork.invoke('page',JSON.stringify({op,token:routeToken,...extra}));
    document.addEventListener('input',e=>{if(e.target.dataset.logQuery){logState(e.target.dataset.logQuery).query=e.target.value;renderPage()}if(e.target.id==='terminal-filter'){terminalFilter=e.target.value;renderPage()}});
    document.addEventListener('change',e=>{const el=e.target;if(el.dataset.logLevel){logState(el.dataset.logLevel).level=el.value;renderPage()}if(el.id==='terminal-status'){terminalStatus=el.value;renderPage()}if(el.id==='terminal-group'){terminalGroup=el.value;renderPage()}if(el.id==='terminal-add'&&el.value){sendExtra('add',{id:el.value});el.value=''}if(el.dataset.terminalColor)sendExtra('color',{id:el.dataset.terminalColor,color:+el.value})});
    document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;for(const [key,field] of [['logWrap','wrap'],['logFollow','follow']])if(el.dataset[key]){const o=logState(el.dataset[key]);o[field]=!o[field];renderPage()}if(el.dataset.logCopy){const id=el.dataset.logCopy,o=logState(id);sendExtra('copyOutput',{text:plainOutput(filteredOutput(id,o.raw||''))})}if(el.dataset.terminalFont)sendExtra('font',{size:Math.max(9,Math.min(18,fontSize+(+el.dataset.terminalFont)))})});
    document.addEventListener('wheel',e=>{const el=e.target.closest('.log');if(el&&e.deltaY<0){logState(el.id).follow=false;const b=document.querySelector('[data-log-follow="'+el.id+'"]');if(b)b.textContent='Follow latest'}},{passive:true});
    window.addEventListener('pagehide',()=>{if(draftTimer)pageSend('draft',terminalID)});
    document.getElementById('page').addEventListener('focusout',e=>{if(e.target.name&&draftTimer)pageSend('draft',e.target.dataset.id||'')});
    const ansiControl=/\x1b(?:\][^\x07\x1b]*(?:\x07|\x1b\\)|\[[0-?]*[ -/]*[@-~])/g;
    const plainOutput=text=>text.replace(ansiControl,'');
    function ansiHTML(text){let color='#99f0ab',bold=false,cursor=0,html='';const palette=['#7a7a7a','#ff707a','#6bd98c','#f5c766','#70bafa','#cfa1f5','#6bd6de','#ffffff'];const segment=t=>!t?'':'<span style="color:'+color+';font-weight:'+(bold?'700':'400')+'">'+esc(t)+'</span>';for(const match of text.matchAll(ansiControl)){html+=segment(text.slice(cursor,match.index));const seq=match[0];if(seq.startsWith('\x1b[')&&seq.endsWith('m')){const codes=seq.slice(2,-1).split(';').map(x=>+x||0);for(let i=0;i<codes.length;i++){const n=codes[i];if(n===0){color='#99f0ab';bold=false}else if(n===1)bold=true;else if(n===22)bold=false;else if(n===39)color='#99f0ab';else if(n>=30&&n<=37)color=palette[n-30];else if(n>=90&&n<=97)color=palette[n-90];else if(n===38||n===48){if(codes[i+1]===2&&i+4<codes.length){if(n===38)color='rgb('+codes.slice(i+2,i+5).map(v=>Math.min(255,Math.max(0,v))).join(',')+')';i+=4}else if(codes[i+1]===5&&i+2<codes.length){const v=Math.min(255,Math.max(0,codes[i+2]));if(n===38){if(v<16)color=palette[v%8];else if(v>=232)color='rgb('+[0,0,0].map(()=>8+(v-232)*10).join(',')+')';else{const c=v-16,channel=x=>x===0?0:55+x*40;color='rgb('+[Math.floor(c/36),Math.floor(c/6)%6,c%6].map(channel).join(',')+')'}}i+=2}}}}cursor=match.index+seq.length}return html+segment(text.slice(cursor))}
    filteredOutput=(id,value)=>{const o=logState(id),query=o.query.trim().toLowerCase();return value.split('\n').filter(line=>{const text=plainOutput(line).toLowerCase(),level=text.startsWith('[input]')?'Inputs':/\b(error|fatal|panic|exception|failed|failure)\b/.test(text)?'Errors':/\b(warn|warning|deprecated)\b/.test(text)?'Warnings':'All lines';return (!query||text.includes(query))&&(o.level==='All lines'||o.level===level)}).join('\n')};
    function setLog(id,value){const el=document.getElementById(id);if(!el)return;const o=logState(id),text=filteredOutput(id,value),html=ansiHTML(text||(!value?'Waiting for output…':'No lines match these filters')),top=el.scrollTop;o.raw=value;if(el.innerHTML!==html){el.innerHTML=html;el.scrollTop=o.follow?el.scrollHeight:top}el.style.fontSize=fontSize+'px';el.style.whiteSpace=o.wrap?'pre-wrap':'pre';el.style.overflowWrap=o.wrap?'anywhere':'normal';const follow=document.querySelector('[data-log-follow="'+id+'"]');if(follow)follow.textContent=o.follow?'Following':'Follow latest'}
    if(notchwork.state)renderPage();
    </script>
